// SVG 1 — ROPE CONSTRUCTION DIAGRAM
// ══════════════════════════════════════
function RopeConstructionSVG({ lang }) {
  const [sel, setSel] = useState(null);

  const parts = [
    { id:"fil", icon:"〰️", color:C.rope,
      label:{fr:"Fil (filament)",en:"Filament/Thread",es:"Filamento/Hilo",pt:"Filamento/Fio"},
      desc:{fr:"FILAMENT / FIL\n\nÉLÉMENT DE BASE de tout cordage.\n\nNATURE :\n→ Fibres naturelles : chanvre, sisal, manille, coton\n→ Fibres synthétiques : nylon, polyester, polypropylène\n→ Fibres métalliques : acier inoxydable, galvanisé\n\nPROPRIÉTÉS :\n→ Diamètre très fin : 0,1 à 1 mm\n→ Résistance unitaire faible\n→ Souplesse maximale\n→ Des milliers de fils composent un cordage\n\nRÔLE : matière première de base\nLa qualité du fil détermine la qualité du cordage",
           en:"FILAMENT / THREAD\n\nBASIC ELEMENT of any rope.\n\nNATURE:\n→ Natural fibres: hemp, sisal, manila, cotton\n→ Synthetic fibres: nylon, polyester, polypropylene\n→ Metal fibres: stainless steel, galvanised\n\nPROPERTIES:\n→ Very small diameter: 0.1 to 1 mm\n→ Low individual breaking strength\n→ Maximum flexibility\n→ Thousands of threads make up one rope\n\nROLE: basic raw material\nThread quality determines rope quality",
           es:"FILAMENTO / HILO\n\nELEMENTO BÁSICO de cualquier cabo.\n\nNATURALEZA:\n→ Fibras naturales: cáñamo, sisal, manila, algodón\n→ Fibras sintéticas: nylon, poliéster, polipropileno\n→ Fibras metálicas: acero inoxidable, galvanizado\n\nPROPIEDADES:\n→ Diámetro muy pequeño: 0,1 a 1 mm\n→ Resistencia unitaria baja\n→ Flexibilidad máxima\n→ Miles de filamentos componen un cabo",
           pt:"FILAMENTO / FIO\n\nELEMENTO BÁSICO de qualquer cabo.\n\nNATUREZA:\n→ Fibras naturais: cânhamo, sisal, manila, algodão\n→ Fibras sintéticas: nylon, poliéster, polipropileno\n→ Fibras metálicas: aço inoxidável, galvanizado\n\nPROPRIEDADES:\n→ Diâmetro muito pequeno: 0,1 a 1 mm\n→ Resistência unitária baixa\n→ Flexibilidade máxima\n→ Milhares de fios compõem um cabo"} },
    { id:"meche", icon:"🌀", color:C.fiber,
      label:{fr:"Mèche (toron élémentaire)",en:"Yarn (elementary strand)",es:"Mecha (filástica)",pt:"Mecha (filástica)"},
      desc:{fr:"MÈCHE / FILIÈRE / FILASSE\n\nASSEMBLAGE DE FILS tordus ensemble.\n\nCONSTRUCTION :\n→ Plusieurs fils tordus en hélice\n→ Sens de torsion : S (gauche) ou Z (droite)\n→ Diamètre : 1 à 5 mm\n\nIMPORTANCE :\n→ La torsion crée une cohésion mécanique\n→ Plus la torsion est serrée = plus rigide\n→ Moins serrée = plus souple\n\nSUR UN CÂBLE ACIER :\nLa mèche = âme (core) centrale\nSouvent en sisal ou plastique pour l'acier\nRôle : maintenir la forme circulaire du toron",
           en:"YARN / FILASSE\n\nASSEMBLY OF THREADS twisted together.\n\nCONSTRUCTION:\n→ Several threads twisted in helix\n→ Twist direction: S (left) or Z (right)\n→ Diameter: 1 to 5 mm\n\nIMPORTANCE:\n→ Twist creates mechanical cohesion\n→ Tighter twist = more rigid\n→ Looser twist = more flexible\n\nIN WIRE ROPE:\nThe yarn = central core\nOften sisal or plastic for steel wire\nRole: maintain circular shape of strand",
           es:"MECHA / FILÁSTICA\n\nCONJUNTO DE HILOS torcidos juntos.\n\nCONSTRUCCIÓN:\n→ Varios hilos torcidos en hélice\n→ Dirección de torsión: S (izquierda) o Z (derecha)\n→ Diámetro: 1 a 5 mm\n\nIMPORTANCIA:\n→ La torsión crea cohesión mecánica\n→ Torsión más apretada = más rígida\n→ Más floja = más flexible",
           pt:"MECHA / FILÁSTICA\n\nCONJUNTO DE FIOS torcidos juntos.\n\nCONSTRUÇÃO:\n→ Vários fios torcidos em hélice\n→ Direção de torção: S (esquerda) ou Z (direita)\n→ Diâmetro: 1 a 5 mm\n\nIMPORTÂNCIA:\n→ A torção cria coesão mecânica\n→ Torção mais apertada = mais rígida\n→ Mais solta = mais flexível"} },
    { id:"toron", icon:"➰", color:C.steel,
      label:{fr:"Toron (strand)",en:"Strand",es:"Torón (cordón)",pt:"Toron (perna)"},
      desc:{fr:"TORON / STRAND\n\nASSEMBLAGE DE MÈCHES tordues en sens inverse.\n\nCONSTRUCTION :\n→ 3 à 19 mèches tordues ensemble\n→ Torsion en sens inverse des mèches\n→ Principe de contre-torsion = solidité\n→ Diamètre : 5 à 30 mm selon usage\n\nIMPORTANCE :\n→ Unité constitutive du cordage\n→ Un câble acier classique : 6 torons\n→ Chaque toron peut avoir 7, 19, 37 fils\n\nNOTATION :\n'6×19' = 6 torons de 19 fils chacun\n'6×37' = 6 torons de 37 fils (plus flexible)\n'3 torons' = cordage textile simple",
           en:"STRAND\n\nASSEMBLY OF YARNS twisted in opposite direction.\n\nCONSTRUCTION:\n→ 3 to 19 yarns twisted together\n→ Twist in opposite direction to yarns\n→ Counter-twist principle = strength\n→ Diameter: 5 to 30 mm depending on use\n\nIMPORTANCE:\n→ Constitutive unit of the rope\n→ Classic wire rope: 6 strands\n→ Each strand can have 7, 19, 37 wires\n\nNOTATION:\n'6×19' = 6 strands of 19 wires each\n'6×37' = 6 strands of 37 wires (more flexible)\n'3-strand' = simple textile rope",
           es:"TORON / CORDÓN\n\nCONJUNTO DE MECHAS torcidas en sentido contrario.\n\nCONSTRUCCIÓN:\n→ 3 a 19 mechas torcidas juntas\n→ Torsión en sentido contrario a las mechas\n→ Principio de contratorsión = resistencia\n→ Diámetro: 5 a 30 mm según uso\n\nIMPORTANCIA:\n→ Unidad constitutiva del cabo\n→ Cable de acero clásico: 6 torones\n→ Notación: '6×19' = 6 torones de 19 hilos",
           pt:"TORON / PERNA\n\nCONJUNTO DE MECHAS torcidas em sentido contrário.\n\nCONSTRUÇÃO:\n→ 3 a 19 mechas torcidas juntas\n→ Torção em sentido contrário às mechas\n→ Princípio de contra-torção = resistência\n→ Diâmetro: 5 a 30 mm conforme o uso\n\nIMPORTÂNCIA:\n→ Unidade constitutiva do cabo\n→ Cabo de aço clássico: 6 torons\n→ Notação: '6×19' = 6 torons de 19 fios"} },
    { id:"cordage", icon:"🔗", color:C.hemp,
      label:{fr:"Cordage (rope)",en:"Rope/Cable",es:"Cabo/Cable",pt:"Cabo/Estropo"},
      desc:{fr:"CORDAGE / CÂBLE\n\nASSEMBLAGE FINAL de torons.\n\nCONSTRUCTION :\n→ 3 torons (cordage commis) : le plus courant en textile\n→ 4 torons : cordage câblé (câblot)\n→ 6 torons + âme : câble acier standard\n→ Tressé (braid) : moderne, sans torsion\n\nÂME (CORE) :\nCœur central du cordage\n→ Âme textile : souplesse\n→ Âme toronné : résistance à la traction\n→ Âme acier : rigidité maximale\n\nMESURE DU CORDAGE :\n→ Diamètre en mm (cordages modernes)\n→ Circonférence en mm (méthode ancienne)\n→ 1 pouce = 25,4 mm de circonférence",
           en:"ROPE / CABLE\n\nFINAL ASSEMBLY of strands.\n\nCONSTRUCTION:\n→ 3-strand (hawser-laid): most common in textile\n→ 4-strand: cable-laid\n→ 6-strand + core: standard wire rope\n→ Braided: modern, no twist\n\nCORE:\nCentral heart of the rope\n→ Fibre core: flexibility\n→ Strand core: tensile strength\n→ Wire core: maximum rigidity\n\nROPE MEASUREMENT:\n→ Diameter in mm (modern ropes)\n→ Circumference in mm (old method)\n→ 1 inch = 25.4 mm circumference",
           es:"CABO / CABLE\n\nCONJUNTO FINAL de torones.\n\nCONSTRUCCIÓN:\n→ 3 torones (colchado): el más común en textil\n→ 4 torones: cabo cableado\n→ 6 torones + alma: cable de acero estándar\n→ Trenzado (braid): moderno, sin torsión\n\nALMA (CORE):\nCorazón central del cabo\n→ Alma textil: flexibilidad\n→ Alma de toron: resistencia a la tracción\n→ Alma de acero: rigidez máxima",
           pt:"CABO / ESTROPO\n\nCONJUNTO FINAL de torons.\n\nCONSTRUÇÃO:\n→ 3 torons (cabo de laborar): o mais comum em têxtil\n→ 4 torons: cabo cableado\n→ 6 torons + alma: cabo de aço padrão\n→ Trançado (braid): moderno, sem torção\n\nALMA (CORE):\nCoração central do cabo\n→ Alma têxtil: flexibilidade\n→ Alma de toron: resistência à tração\n→ Alma de aço: rigidez máxima"} },
  ];

  // SVG Schema of rope construction
  const RopeSchema = () => (
    <svg viewBox="0 0 320 100" style={{width:"100%",height:90,marginBottom:8}}>
      {/* Background */}
      <rect width="320" height="100" fill="rgba(0,0,0,0.3)" rx="10"/>
      {/* Labels */}
      <text x="20" y="20" fill={C.rope} fontSize="9" fontFamily="monospace">FIL</text>
      <text x="90" y="20" fill={C.fiber} fontSize="9" fontFamily="monospace">MÈCHE</text>
      <text x="170" y="20" fill={C.steel} fontSize="9" fontFamily="monospace">TORON</text>
      <text x="250" y="20" fill={C.hemp} fontSize="9" fontFamily="monospace">CORDAGE</text>
      {/* Arrow */}
      <text x="60" y="60" fill={C.muted} fontSize="16">→</text>
      <text x="138" y="60" fill={C.muted} fontSize="16">→</text>
      <text x="218" y="60" fill={C.muted} fontSize="16">→</text>
      {/* Icons */}
      <circle cx="35" cy="58" r="8" fill={C.rope} opacity="0.8"/>
      <circle cx="110" cy="58" r="12" fill={C.fiber} opacity="0.7"/>
      <circle cx="110" cy="58" r="6" fill={C.rope} opacity="0.6"/>
      <circle cx="195" cy="58" r="16" fill={C.steel} opacity="0.6"/>
      <circle cx="195" cy="48" r="8" fill={C.fiber} opacity="0.7"/>
      <circle cx="195" cy="68" r="8" fill={C.fiber} opacity="0.7"/>
      <circle cx="285" cy="55" r="20" fill={C.hemp} opacity="0.5"/>
      <circle cx="272" cy="48" r="9" fill={C.steel} opacity="0.6"/>
      <circle cx="285" cy="68" r="9" fill={C.steel} opacity="0.6"/>
      <circle cx="298" cy="48" r="9" fill={C.steel} opacity="0.6"/>
      {/* Scale labels */}
      <text x="27" y="82" fill={C.rope} fontSize="7" fontFamily="monospace">0.1mm</text>
      <text x="100" y="82" fill={C.fiber} fontSize="7" fontFamily="monospace">1-5mm</text>
      <text x="180" y="82" fill={C.steel} fontSize="7" fontFamily="monospace">5-30mm</text>
      <text x="265" y="82" fill={C.hemp} fontSize="7" fontFamily="monospace">8-200mm</text>
    </svg>
  );

  const sel_ = sel!==null ? parts[sel] : null;
  return (
    <div>
      <RopeSchema/>
      <div style={{fontSize:9,color:C.muted,textAlign:"center",marginBottom:10,letterSpacing:1}}>
        {lang==="fr"?"CONSTRUCTION D'UN CORDAGE — APPUYEZ POUR DÉTAILS":lang==="en"?"ROPE CONSTRUCTION — TAP FOR DETAILS":"CONSTRUCCIÓN DE UN CABO — PULSA PARA DETALLES"}
      </div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6,marginBottom:10}}>
        {parts.map((p,i)=>(
          <div key={i} onClick={()=>setSel(sel===i?null:i)} style={{
            padding:"8px 6px",borderRadius:12,cursor:"pointer",textAlign:"center",
            background:sel===i?`${p.color}22`:"rgba(255,255,255,0.04)",
            border:`1.5px solid ${sel===i?p.color:"rgba(255,255,255,0.08)"}`}}>
            <div style={{fontSize:16,marginBottom:2}}>{p.icon}</div>
            <div style={{fontSize:9,fontWeight:700,color:sel===i?p.color:C.muted,lineHeight:1.2}}>{p.label[lang]||p.label.en}</div>
          </div>
        ))}
      </div>
      {sel_&&<div style={{padding:"12px",borderRadius:14,background:`${sel_.color}10`,border:`1.5px solid ${sel_.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:11,fontWeight:700,color:sel_.color,marginBottom:8}}>{sel_.icon} {sel_.label[lang]||sel_.label.en}</div>
        <div style={{fontFamily:"'Courier New',monospace",fontSize:11,color:C.white,lineHeight:1.7,whiteSpace:"pre-line"}}>{sel_.desc[lang]||sel_.desc.en}</div>
      </div>}
    </div>
  );
}

