// SVG 4 — ROPE INSPECTION & CARE
// ══════════════════════════════════════
function RopeInspectionSVG({ lang }) {
  const [idx, setIdx] = useState(0);

  const checks = [
    { icon:"👁️", color:C.rope,
      title:{fr:"Inspection visuelle",en:"Visual inspection",es:"Inspección visual",pt:"Inspeção visual"},
      signs:{fr:"SIGNES DE MISE AU REBUT :\n\nCÂBLE ACIER :\n→ 10% fils brisés dans 1 pas de câblage = rebut\n→ Toron brisé = rebut immédiat\n→ Rouille de surface : nettoyer, graisser\n→ Écrasement, déformation, pincure : rebut\n→ Corrosion intérieure : inspecter âme\n→ Gorge prononcée (kinking) : rebut\n\nCORDAGE TEXTILE :\n→ Fibres coupées ou brûlées\n→ Taches bleues/noires (moisissures) : rincer\n→ Élasticité disparue\n→ Traînées de rouille (contact métal)\n→ Gonflement anormal : abrasion interne\n→ Déformation de la tresse (ovale au lieu de rond)",
             en:"REJECTION CRITERIA:\n\nWIRE ROPE:\n→ 10% broken wires in 1 lay length = reject\n→ Broken strand = immediate rejection\n→ Surface rust: clean, re-grease\n→ Crushing, deformation, kinking: reject\n→ Internal corrosion: inspect core\n→ Severe kinking: reject\n\nTEXTILE ROPE:\n→ Cut or burnt fibres\n→ Blue/black stains (mould): rinse\n→ Lost elasticity\n→ Rust streaks (metal contact)\n→ Abnormal swelling: internal abrasion\n→ Braid deformation (oval instead of round)",
             es:"CRITERIOS DE RECHAZO:\n\nCABLE DE ACERO:\n→ 10% hilos rotos en 1 paso de cableado = rechazo\n→ Toron roto = rechazo inmediato\n→ Oxidación superficial: limpiar, engrasas\n→ Aplastamiento, deformación, vuelta de campana: rechazo\n\nCABO TEXTIL:\n→ Fibras cortadas o quemadas\n→ Manchas azules/negras (moho): enjuagar\n→ Elasticidad perdida",
             pt:"CRITÉRIOS DE REJEIÇÃO:\n\nCABO DE AÇO:\n→ 10% fios partidos em 1 passo de cablagem = rejeitar\n→ Toron partido = rejeição imediata\n→ Ferrugem superficial: limpar, engorduras\n→ Esmagamento, deformação, torção: rejeitar\n\nCABO TÊXTIL:\n→ Fibras cortadas ou queimadas\n→ Manchas azuis/negras (bolor): enxaguar\n→ Elasticidade perdida"} },
    { icon:"🔧", color:C.fiber,
      title:{fr:"Entretien courant",en:"Routine maintenance",es:"Mantenimiento rutinario",pt:"Manutenção de rotina"},
      signs:{fr:"ENTRETIEN CÂBLE ACIER :\n\n→ Graissage régulier (tous les 3 mois en exploitation)\n→ Graisse pénétrante pour l'âme\n→ Nettoyer la vase, le sel, les débris d'abord\n→ Inspecter les cosses et manilles\n→ Vérifier les coinceurs (sertissages)\n\nENTRETIEN CORDAGES TEXTILES :\n→ Rincer à l'eau douce après usage en mer\n→ Sécher à l'ombre (UV dégradent les fibres)\n→ Stockage : propre, sec, à l'abri de la chaleur\n→ Jamais en contact direct avec produits chimiques\n→ Ne pas laisser sur le pont au soleil\n\nFREQUENCE D'INSPECTION :\n→ Avant chaque usage pour cordes de sécurité\n→ Mensuelle pour cordages courants\n→ Annuelle par bureau de contrôle agréé (levage)",
             en:"WIRE ROPE MAINTENANCE:\n\n→ Regular greasing (every 3 months in service)\n→ Penetrating grease for the core\n→ Clean mud, salt, debris first\n→ Inspect thimbles and shackles\n→ Check swaged fittings\n\nTEXTILE ROPE MAINTENANCE:\n→ Rinse with fresh water after sea use\n→ Dry in shade (UV degrades fibres)\n→ Storage: clean, dry, away from heat\n→ Never in direct contact with chemicals\n→ Do not leave on deck in sun\n\nINSPECTION FREQUENCY:\n→ Before each use for safety ropes\n→ Monthly for working lines\n→ Annual by approved inspection body (lifting)",
             es:"MANTENIMIENTO CABLE DE ACERO:\n\n→ Engrase regular (cada 3 meses en servicio)\n→ Grasa penetrante para el alma\n→ Limpiar barro, sal, residuos primero\n\nMANTENIMIENTO CABO TEXTIL:\n→ Aclarar con agua dulce tras uso en el mar\n→ Secar a la sombra (los UV degradan las fibras)\n→ Almacenamiento: limpio, seco, lejos del calor\n→ Nunca en contacto directo con productos químicos",
             pt:"MANUTENÇÃO CABO DE AÇO:\n\n→ Lubrificação regular (a cada 3 meses em serviço)\n→ Graxa penetrante para a alma\n→ Limpar lama, sal, detritos primeiro\n\nMANUTENÇÃO CABO TÊXTIL:\n→ Enxaguar com água doce após uso no mar\n→ Secar à sombra (os UV degradam as fibras)\n→ Armazenamento: limpo, seco, longe do calor\n→ Nunca em contacto direto com produtos químicos"} },
    { icon:"⚠️", color:C.steel,
      title:{fr:"Sécurité & Dangers",en:"Safety & Hazards",es:"Seguridad y Peligros",pt:"Segurança e Perigos"},
      signs:{fr:"DANGERS PRINCIPAUX :\n\nEFFET DE RETOUR (snapback) :\n→ DANGER DE MORT lors de rupture brusque\n→ Zone de danger : triangle devant la bitte\n→ Ne JAMAIS se tenir dans la zone de retour\n→ Porter équipement de protection (gants, casque)\n\nFILS BRISÉS (câble acier) :\n→ Piquent et peuvent perforer les gants\n→ Toujours inspecter avec un chiffon\n→ Porter des gants de manutention renforcés\n\nSURCHARGE :\n→ Ne jamais dépasser la CMU (Charge Max. Utilisation)\n→ Facteur de sécurité = résistance à la rupture / CMU\n→ Le choc multiplie la charge × 2 à 5 fois\n→ Un cordage usé peut rompre à 50% de sa CMU\n\nSTOCKAGE INCORRECT :\n→ Nœuds permanents = points de faiblesse\n→ Contact avec acide/huile : dégrade immédiatement\n→ Câble mal lové = torsions = fragilisation",
             en:"MAIN HAZARDS:\n\nSNAPBACK:\n→ FATAL RISK on sudden failure\n→ Danger zone: triangle in front of bitt\n→ NEVER stand in snapback zone\n→ Wear protective equipment (gloves, helmet)\n\nBROKEN WIRES (wire rope):\n→ Pierce and can perforate gloves\n→ Always inspect with a cloth\n→ Wear reinforced handling gloves\n\nOVERLOADING:\n→ Never exceed the SWL (Safe Working Load)\n→ Safety factor = breaking load / SWL\n→ Shock multiplies load × 2 to 5 times\n→ Worn rope can fail at 50% SWL\n\nINCORRECT STORAGE:\n→ Permanent knots = weak points\n→ Contact with acid/oil: immediate degradation\n→ Badly coiled cable = twists = weakening",
             es:"PELIGROS PRINCIPALES:\n\nEFECTO DE RETORNO (snapback):\n→ RIESGO DE MUERTE en caso de rotura brusca\n→ Zona de peligro: triángulo delante de la bita\n→ NUNCA pararse en la zona de retorno\n→ Llevar equipamiento de protección\n\nHILOS ROTOS (cable de acero):\n→ Pincan y pueden perforar los guantes\n→ Siempre inspeccionar con un trapo\n\nSOBRECARGA:\n→ Nunca superar la CMU (Carga Máxima de Utilización)\n→ El choque multiplica la carga × 2 a 5 veces",
             pt:"PERIGOS PRINCIPAIS:\n\nEFEITO DE RETORNO (snapback):\n→ RISCO DE MORTE em caso de rotura brusca\n→ Zona de perigo: triângulo à frente da bita\n→ NUNCA se colocar na zona de retorno\n→ Usar equipamento de proteção\n\nFIOS PARTIDOS (cabo de aço):\n→ Picam e podem perfurar as luvas\n→ Sempre inspecionar com um pano\n\nSOBRECARGA:\n→ Nunca exceder a CMU (Carga Máx. Utilização)\n→ O choque multiplica a carga × 2 a 5 vezes"} },
  ];

  const c = checks[idx];
  return (
    <div>
      <div style={{display:"flex",gap:8,marginBottom:10}}>
        {checks.map((ch,i)=>(
          <div key={i} onClick={()=>setIdx(i)} style={{
            flex:1,padding:"8px 4px",borderRadius:10,cursor:"pointer",textAlign:"center",
            background:idx===i?`${ch.color}22`:"rgba(255,255,255,0.04)",
            border:`1.5px solid ${idx===i?ch.color:"rgba(255,255,255,0.08)"}`}}>
            <div style={{fontSize:16,marginBottom:2}}>{ch.icon}</div>
            <div style={{fontSize:8,color:idx===i?ch.color:C.muted,fontWeight:700,lineHeight:1.2}}>{ch.title[lang]||ch.title.en}</div>
          </div>
        ))}
      </div>
      <div style={{padding:"12px",borderRadius:14,background:`${c.color}10`,border:`1.5px solid ${c.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:11,fontWeight:700,color:c.color,marginBottom:8}}>{c.icon} {c.title[lang]||c.title.en}</div>
        <div style={{fontFamily:"'Courier New',monospace",fontSize:11,color:C.white,lineHeight:1.7,whiteSpace:"pre-line"}}>{c.signs[lang]||c.signs.en}</div>
      </div>
    </div>
  );
}

